  if (o.ui.dialogue || o.ui.retry) { a.skip = true; return a; }
  if (o.ui.choice) { a.choose = 1; return a; }
  const g = o.gps, gl = o.goal, R = o.rays, me = o.me, car = o.car;
  const gd = gl ? gl.d : 999, pulse = o.t % 1 < 0.1, n = Math.floor(o.t);
  const txt = o.mission.text || '';
  // stall check every 2 s; back out briefly if stuck (not while bailing out of a car)
  if (m.st === undefined || o.t - m.st >= 2) {
    const mv = m.st === undefined ? 9 : Math.hypot(me.x - m.sx, me.z - m.sz);
    if (mv < 1.2 && gd > 8 && !(me.mode === 'car' && m.hold)) m.rec = o.t + 2;
    m.sx = me.x; m.sz = me.z; m.st = o.t;
  }
  if (me.mode === 'entering') return a;
  const rec = o.t < (m.rec || 0);
  // a gang member or hostile civilian within 9 m
  let threat = false;
  for (const k of o.peds) if ((k.hostile || k.kind === 'gang') && k.d < 9) threat = true;
  if (me.mode === 'car') {
    m.hold = false;
    const needOut = gl && (gl.kind === 'person' || (gl.kind === 'place' && (!o.mission.name || /talk|goon|inside|collect|on foot|get out/i.test(txt))));
    // bail out of a burning or wrecked car (remember it so we do not climb back in); or leave near an on-foot goal
    if (car.burning || car.hp < 0.2 || (needOut && gd < 14)) {
      a.brake = car.spd > 1.5 ? 1 : 0; a.use = car.spd < 2 && pulse; m.hold = true;
      if (car.burning || car.hp < 0.2) m.bail = o.t;
      return a;
    }
    if (!g) { a.gas = 0.4; a.steer = R[4] > R[2] ? 0.3 : -0.3; return a; }
    if (rec) { a.brake = 1; a.steer = n % 2 ? 1 : -1; return a; }
    let s = g.b * 1.6;
    if (R[3] < 10) s += (R[4] > R[2] ? 1 : -1) * 0.6 * (1 - R[3] / 10);
    if (R[1] < 3) s += 0.4;
    if (R[5] < 3) s -= 0.4;
    const turn = Math.max(Math.abs(g.b), Math.abs(g.b2) * 0.9, Math.abs(g.b3) * 0.6);
    let want = turn > 0.9 ? 5 : turn > 0.5 ? 9 : turn > 0.25 ? 14 : 20;
    if (g.wd < 12 && Math.abs(g.b) > 0.5) want = Math.min(want, 5);
    want = Math.min(want, 2 + R[3] * 1.1);
    if (gd < 25) want = Math.min(want, 4 + gd / 2);
    let hot = false;
    for (const k of o.cars) {
      if (k.f > 0 && k.f < 18 && Math.abs(k.r) < 2.6) {
        s += (k.r > 0 ? -1 : 1) * 0.35 * (1 - k.f / 18);
        if (k.kind !== 'parked') { want = Math.min(want, Math.max(2, k.spd * 0.9)); if (k.f < 8) hot = true; }
        else if (k.f < 6 && Math.abs(k.r) < 1.6) want = Math.min(want, 3);
      }
    }
    for (const k of o.peds) if (k.f > 0 && k.f < 14 && Math.abs(k.r) < 2.5) { want = Math.min(want, 3); if (k.f < 8) hot = true; }
    if (threat) want = Math.max(want, 12); // keep moving away from hostiles
    a.steer = c(s, -1, 1);
    a.gas = car.spd < want && !hot ? 1 : 0;
    a.brake = hot && car.spd > 1 ? 1 : car.spd > want + 3 ? 0.6 : 0;
    if (Math.abs(car.lat) > 4 && car.spd > 10) a.gas = 0;
    return a;
  }
  // on foot
  const e = o.enter, far = gd > 50, fresh = o.t - (m.bail || -99) > 15;
  // climb into the job car, or a free car when the goal is far (not one we just bailed out of)
  if (e && e.free && e.d < 3.2 && (e.goal || (far && fresh))) { a.use = pulse; return a; }
  let b = g ? g.b : gl ? gl.b : 0.3;
  if (gl && gd < 150 && R[3] > 10 && R[2] > 6 && R[4] > 6) b = gl.b;
  if (far || (gl && gl.kind === 'car' && gl.free)) {
    let t = null;
    for (const k of o.cars) if (k.free && k.kind === 'parked' && k.d < 35 && (!t || k.d < t.d)) t = k;
    if (t && fresh && (far || t.goal)) b = t.b;
    if (gl && gl.kind === 'car' && gl.free) b = gl.b;
  }
  // at the debtor: talk, unless someone hostile is close
  if (gl && gl.kind === 'person' && gd < 3 && !threat) { a.talk = true; a.turn = c(gl.b * 2, -1, 1); return a; }
  // steer around people (hostiles at a wider berth) and keep off the road
  let av = 0, close = false;
  for (const k of o.peds) {
    if (k.f < -1 || k.d > 9) continue;
    if (gl && gl.kind === 'person' && Math.abs(k.d - gd) < 1.5) continue;
    const bad = k.hostile || k.kind !== 'civ', L = bad ? 9 : 5;
    if (k.d < L && Math.abs(k.r) < 3) av -= (k.r >= 0 ? 1 : -1) * (L - k.d) / 4 * (bad ? 1.5 : 1);
    if (k.d < 2) close = true;
  }
  for (const k of o.cars) if (k.kind === 'traffic' && k.f > -2 && k.f < 6 && Math.abs(k.r) < 2.5) close = true;
  let t = b * 2.2 + av * 0.6;
  if (R[3] < 3) t += (R[4] > R[2] ? 1 : -1) * 0.8;
  if (R[2] < 1.5) t += 0.5;
  if (R[4] < 1.5) t -= 0.5;
  a.turn = c(t, -1, 1);
  a.move = threat ? 1 : close ? 0.3 : Math.abs(b) > 1.2 ? 0.2 : R[3] < 1.2 ? 0.4 : 1;
  a.sprint = threat || (Math.abs(b) < 0.4 && R[3] > 6 && Math.abs(av) < 0.5);
  if (rec) { a.move = -0.8; a.sprint = false; a.strafe = n % 2 ? 1 : -1; a.jump = pulse; }
  return a;
}
